    public static JsonObject SystemMessage(bool isWindows) => new()
    {
        ["role"] = "system",
        ["content"] = $"""
            You are an autonomous, cross-platform coding agent.
            PLATFORM: {(isWindows ? "Windows - use cmd.exe syntax" : "Unix - use bash/sh syntax")}

            RULES:
