                    await _observer.OnDone("Task complete.");
                    await MemoryStore.SaveAsync(memoryFile, messages);
                    return;
                }

                await _observer.OnDone("Assistant finished.");
                return;
            }

            // Execute each tool call
            foreach (var tc in toolCalls)
